export const title = "How to Mount a Cable Tray Without Blocking Your Knees";
export const metaTitle = "How to Mount a Cable Tray Without Blocking Your";
export const metaDescription = "Reserve legroom before storing cables. Practical measurements, original diagrams and fit checks for cable management in small workspaces.";
export const author = "Jamie Cole, Lead Product Researcher";
